"""Direct check -> visible result -> save/activate, with exact registered identity."""
JS=r'''
let uploadCompanies=[],uploadCompanyTouched=false,uploadSavedReceipt=null;
$('workbook-revision').checked=true;
function showWorkbookReview(){const step=$('upload-step-3');step.open=true;step.scrollIntoView({behavior:'smooth',block:'start'});$('workbook-summary').setAttribute('tabindex','-1');$('workbook-summary').focus({preventScroll:true})}
function uploadProgress(text){$('upload-file-progress').textContent=text}
function applyUploadCompany(id){const found=uploadCompanies.find(c=>c.company_id===id),fresh=id==='__NEW__';if(!found&&!fresh)return;for(const key of ['reception-company-id','reception-company-name'])$(key).readOnly=!fresh;$('reception-material').disabled=!fresh;if(found){$('reception-company-id').value=found.company_id;$('reception-company-name').value=found.legal_name;$('reception-material').value=found.material_nature}else{$('reception-company-id').value='';$('reception-company-name').value='';$('reception-material').value='SYNTHETIC'}$('upload-company-info').textContent=found?'Empresa seleccionada: '+found.legal_name+' · '+found.company_id+'. Se utilizan sus datos registrados; puedes cambiar la fecha de corte.':'Introduce los datos de una empresa nueva. Para actualizar una existente, selecciónala en la lista.';workbookInvalidate();$('workbook-activate-on-save').disabled=$('reception-material').value!=='SYNTHETIC';$('workbook-activate-on-save').checked=$('reception-material').value==='SYNTHETIC'}
function syncUploadCompanySelection(){if(!$('reception-cutoff').value&&state?.info?.as_of_date)$('reception-cutoff').value=stockDate(state.info.as_of_date);if(uploadCompanyTouched||!uploadCompanies.length)return;const id=state?.info?.company?.company_id;if(uploadCompanies.some(c=>c.company_id===id)){$('upload-company-existing').value=id;applyUploadCompany(id)}}
async function loadUploadCompanies(){try{uploadCompanies=await api('/api/reception/companies');const select=$('upload-company-existing');select.replaceChildren();option(select,'','Selecciona una empresa existente');uploadCompanies.forEach(c=>option(select,c.company_id,c.legal_name+' · '+c.company_id+' · '+(c.material_nature==='SYNTHETIC'?'Ficticia':'Real')));option(select,'__NEW__','Crear una empresa nueva');syncUploadCompanySelection()}catch(e){$('upload-company-info').textContent='No se pudo cargar la lista de empresas: '+e.message}}
const uploadCompanyLabel=document.createElement('label');uploadCompanyLabel.textContent='Empresa a la que pertenece esta nueva versión';const uploadCompanySelect=document.createElement('select');uploadCompanySelect.id='upload-company-existing';uploadCompanyLabel.append(uploadCompanySelect);const uploadCompanyInfo=document.createElement('p');uploadCompanyInfo.id='upload-company-info';uploadCompanyInfo.setAttribute('role','status');$('upload-context').prepend(uploadCompanyLabel,uploadCompanyInfo);uploadCompanySelect.onchange=()=>{uploadCompanyTouched=true;applyUploadCompany(uploadCompanySelect.value)};
const progress=document.createElement('p');progress.id='upload-file-progress';progress.setAttribute('role','status');$('workbook-check').after(progress);
const activateLabel=document.createElement('label');activateLabel.className='st-check';const activateBox=document.createElement('input');activateBox.id='workbook-activate-on-save';activateBox.type='checkbox';activateBox.checked=true;activateLabel.append(activateBox,document.createTextNode(' Usar este libro como expediente activo al guardarlo. La versión anterior se conserva como histórico.'));$('workbook-save').before(activateLabel);$('workbook-save').textContent='Guardar y usar este archivo';activateBox.onchange=()=>{$('workbook-save').textContent=activateBox.checked?'Guardar y usar este archivo':'Guardar sin activar'};
const outcome=document.createElement('p');outcome.id='upload-save-outcome';outcome.setAttribute('role','status');outcome.textContent='Este archivo todavía no se ha guardado.';$('upload-step-4').prepend(outcome);$('upload-next-finish').disabled=true;
const retry=document.createElement('button');retry.type='button';retry.id='upload-retry-activation';retry.textContent='Reintentar activación del archivo guardado';retry.hidden=true;retry.onclick=async()=>{if(!uploadSavedReceipt)return;retry.disabled=true;try{await activateGuidedReceipt(uploadSavedReceipt);retry.hidden=true}catch(e){outcome.textContent='El archivo está guardado, pero no se ha activado: '+e.message}finally{retry.disabled=false}};outcome.after(retry);
async function activateGuidedReceipt(saved){const dataset=$('dataset').value;const current=await api('/api/state?dataset='+encodeURIComponent(dataset));if(dataset!==$('dataset').value)throw Error('La empresa seleccionada cambió. Repite la activación.');const r=await api('/api/workbook-source/activate',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,context_fingerprint:current.documentary_context.fingerprint,batch_id:saved.batch_id,from_received:true})});await datasets(r.dataset_id);await received();uploadCompanyTouched=false;await loadUploadCompanies();$('upload-step-4').open=true;$('upload-step-4').scrollIntoView({behavior:'smooth',block:'start'});outcome.textContent='GUARDADO Y ACTIVO · '+r.filename+' · Corte '+stockDate(r.as_of_date)+'. EIOS trabaja con esta versión. La anterior se conserva como histórico.';$('upload-next-finish').disabled=false;uploadProgress(outcome.textContent);$('workbook-summary').textContent=outcome.textContent;$('workbook-save').hidden=true;return r}
loadUploadCompanies();
'''
